    result = []
    while A > 0 or B > 0:
        if A > B:
            if A >= 2:
                result.append('aa')
                A -= 2
            else:
                result.append('a')
                A -= 1
            if B > 0:
                result.append('b')
                B -= 1
        elif B > A:
            if B >= 2:
                result.append('bb')
                B -= 2
            else:
                result.append('b')
                B -= 1
            if A > 0:
                result.append('a')
                A -= 1
        else:
            if A > 0:
                result.append('a')
                A += -1
